	int rmem, err = -ENOMEM;
	spinlock_t *busy = NULL;
	int size, rcvbuf;


	rmem = atomic_read(&sk->sk_rmem_alloc);
	rcvbuf = READ_ONCE(sk->sk_rcvbuf);
	if (rmem > rcvbuf)
