		i += len;
		if (get_user(c, &buffer[i]))
			return -EFAULT;

		i++;
		pkt_dev->n_imix_entries++;

		if (pkt_dev->n_imix_entries > MAX_IMIX_ENTRIES)
			return -E2BIG;
	} while (c == ' ');

